    `},{nombre:"Fernando Andrés Pinzón Verbel",name:"Fernando Pinzón",role:"Dependiente Judicial",roleLabel:"Dependiente Judicial",specialty:"Gestión Procesal y Apoyo Legal",shortBio:"Estudiante de Derecho, encargado de verificación, radicación y seguimiento de procesos judiciales.",description:"Estudiante de sexto semestre de Derecho, realiza funciones de verificación y radicación de documentos, seguimiento de procesos y apoyo en la gestión.",image:"/img/socios/fernando.webp",heroImage:"https://images.unsplash.com/photo-1521791136064-7986c2920216?w=1200&q=80",slug:"fernando-pinzon",linkedin:"",whatsapp:"https://wa.me/573242757680",email:"f.pinzon@erabogados.com",specialties:["Gestión Procesal","Radicación de Documentos","Seguimiento de Procesos"],education:["Estudiante de Derecho — Sexto semestre"],content:`
